window.ScripturaLexicons.BDAG_PART_0218 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0218-01\" data-source=\"BDAG\" data-search=\"λευκοβύσσινος remissão veja λευκός BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λευκοβύσσινος</td><td>remissão</td><td>veja λευκός</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0218-02\" data-source=\"BDAG\" data-search=\"λευκός, ή, όν adjetivo branco; brilhante; reluzente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λευκός, ή, όν</td><td>adjetivo</td><td>branco; brilhante; reluzente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0218-03\" data-source=\"BDAG\" data-search=\"λέων, οντος, ὁ substantivo masculino leão; símbolo de perigo e força BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λέων, οντος, ὁ</td><td>substantivo masculino</td><td>leão; símbolo de perigo e força</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0218-04\" data-source=\"BDAG\" data-search=\"λήθη, ης, ἡ substantivo feminino esquecimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λήθη, ης, ἡ</td><td>substantivo feminino</td><td>esquecimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0218-05\" data-source=\"BDAG\" data-search=\"λῆμμα, ατος, τό substantivo neutro aquilo que se recebe; ganho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λῆμμα, ατος, τό</td><td>substantivo neutro</td><td>aquilo que se recebe; ganho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0218-06\" data-source=\"BDAG\" data-search=\"λῆμψις, εως, ἡ substantivo feminino recebimento; débito e crédito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λῆμψις, εως, ἡ</td><td>substantivo feminino</td><td>recebimento; débito e crédito</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0218-07\" data-source=\"BDAG\" data-search=\"ληνός, οῦ, ἡ substantivo feminino cuba; lagar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ληνός, οῦ, ἡ</td><td>substantivo feminino</td><td>cuba; lagar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0218-08\" data-source=\"BDAG\" data-search=\"λῆρος, ου, ὁ substantivo masculino disparate; conversa fiada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λῆρος, ου, ὁ</td><td>substantivo masculino</td><td>disparate; conversa fiada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0218-09\" data-source=\"BDAG\" data-search=\"ληρώδης, ες adjetivo insensato; frívolo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ληρώδης, ες</td><td>adjetivo</td><td>insensato; frívolo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0218-10\" data-source=\"BDAG\" data-search=\"λῃστής, οῦ, ὁ substantivo masculino salteador; bandido; insurgente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λῃστής, οῦ, ὁ</td><td>substantivo masculino</td><td>salteador; bandido; insurgente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0218-11\" data-source=\"BDAG\" data-search=\"λῆψις remissão veja λῆμψις BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λῆψις</td><td>remissão</td><td>veja λῆμψις</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0218-12\" data-source=\"BDAG\" data-search=\"λίαν advérbio muito; extremamente; sobremaneira BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λίαν</td><td>advérbio</td><td>muito; extremamente; sobremaneira</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0218-13\" data-source=\"BDAG\" data-search=\"λίβα remissão veja λίψ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λίβα</td><td>remissão</td><td>veja λίψ</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0218-14\" data-source=\"BDAG\" data-search=\"Λίβανος, ου, ὁ nome próprio masculino Líbano, cadeia montanhosa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Λίβανος, ου, ὁ</td><td>nome próprio masculino</td><td>Líbano, cadeia montanhosa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0218-15\" data-source=\"BDAG\" data-search=\"λίβανος, ου, ὁ substantivo masculino olíbano; incenso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λίβανος, ου, ὁ</td><td>substantivo masculino</td><td>olíbano; incenso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0218-16\" data-source=\"BDAG\" data-search=\"λιβανωτός, οῦ, ὁ substantivo masculino incenso; incensário BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λιβανωτός, οῦ, ὁ</td><td>substantivo masculino</td><td>incenso; incensário</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0218-17\" data-source=\"BDAG\" data-search=\"Λιβερτῖνος, ου, ὁ substantivo masculino liberto; pessoa alforriada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Λιβερτῖνος, ου, ὁ</td><td>substantivo masculino</td><td>liberto; pessoa alforriada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0218-18\" data-source=\"BDAG\" data-search=\"Λιβύη, ης, ἡ nome próprio feminino Líbia, região da África BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Λιβύη, ης, ἡ</td><td>nome próprio feminino</td><td>Líbia, região da África</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0218-19\" data-source=\"BDAG\" data-search=\"Λιβυστῖνος remissão veja Λιβερτῖνος BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Λιβυστῖνος</td><td>remissão</td><td>veja Λιβερτῖνος</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0218-20\" data-source=\"BDAG\" data-search=\"λιθάζω verbo apedrejar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λιθάζω</td><td>verbo</td><td>apedrejar</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0218-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λευκοβύσσινος</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λευκοβύσσινος</span> veja <span class=\"greek\">λευκός</span>, acepção 2, ao final.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0218-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λευκός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λευκός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (veja <span class=\"greek\">λευκαίνω</span>; Hom.+; ins, pap, LXX, En; TestSol 5:13; Test12Patr; JosAs; ParJer 9:18; Philo, Joseph.; SibOr 3, 617; 622; empréstimo na literatura rabínica Figuradamente [com <span class=\"greek\">οἱ</span> <span class=\"greek\">συνιέντες</span>]: <span class=\"greek\">οἱ</span> <span class=\"greek\">λευκοί</span> Iren.1, 19, 2 [Harv. I 177, 1])</p><p class=\"entry-text\">① brilhante, resplandecente, reluzente (Homero e outros) <span class=\"greek\">λ</span>. <span class=\"greek\">ὡς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> (Il. 14, 185 <span class=\"greek\">λ</span>. <span class=\"greek\">ἠέλιος</span> <span class=\"greek\">ὡς</span>) brilhante como a luz <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:2</a>. <span class=\"greek\">λ</span>. <span class=\"greek\">ἐξαστράπτων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:29</a>. Esta acepção também é possível em algumas das passagens seguintes.</p><p class=\"entry-text\">② branco (incluindo, para os gregos, muitos matizes dessa cor e sempre em oposição a <span class=\"greek\">μέλας</span>; cf. nosso vinho «branco») quanto aos cabelos (Tyrtaeus [século VII a.C.] 7, 23 dos cabelos de um idoso; Soph., Ant. 1092; Lev 13:3ff) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:36</a> (em oposição a <span class=\"greek\">μέλας</span>, como em Menandro, Samian 262 [Bodmer p. 61 app.=OxfT p. 259] quanto a Androcles, que tinge seus cabelos brancos); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:14a</a>. Quanto a uma pele de cabra Hv 5:1; Hs 6, 2, 5. Quanto a uma pequena pedra, usada para votar etc. (Lucian, Harmonides 3 p. 855f <span class=\"greek\">ψῆφον</span> … <span class=\"greek\">τὴν</span> <span class=\"greek\">λευκὴν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σώζουσαν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:17</a>. Quanto à lã (PRyl 146, 15 [39 d.C.]; Da 7:9 <span class=\"greek\">ὡσεὶ</span> <span class=\"greek\">ἔριον</span> <span class=\"greek\">λ</span>.; En 106:2; ParJer 9:18) 1:14b. Quanto aos cavalos apocalípticos (cf. JosAs 5:5; Zech 1:8. Veja <span class=\"greek\">πυρρός</span>) 6:2; 19:11, 14a. Quanto a um monstro apocalíptico com as cores preta, vermelha, dourada e branca Hv 4, 1, 10; cf. 4, 3, 5. Quanto a uma nuvem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:14</a>. Quanto às pedras (Michel 509, 17 [241 a.C.]; OGI 219, 36; 268, 17; 339, 34; 105; e outros, em inscrições) Hv 3, 2, 8; 3, 5, 1; 3, 6, 5; Hs 9, 4, 5; 9, 6, 4; 9, 8, 5; 9, 9, 1. Quanto a uma cadeira v 1, 2, 2. Quanto a campos de cereal maduro <span class=\"greek\">λ</span>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">θερισμόν</span> brancos para a ceifa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:35</a>. Quanto a um monte Hs 9, 1, 10; 9, 29, 1; 9, 30, 1f; 4. Quanto a uma rocha 9, 2, 1. Quanto a um trono <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 20:11</a>. Quanto a vestimentas (Plut., Aristid. 21, 4 veste festiva; IPriene 205 <span class=\"greek\">εἰσίναι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱερὸν</span> <span class=\"greek\">ἁγνὸν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐσθῆτι</span> <span class=\"greek\">λευκῇ</span>; POxy 471, 95ff; 531, 13; PGM 4, 636; Eccl 9:8; 2 Macc 11:8; Jos., Bell. 2, 1, Ant. 11, 327; TestLevi 8:2; JosAs 5:6 <span class=\"greek\">χιτῶνα</span> <span class=\"greek\">λευκόν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:3</a>; 16:5 (Lucian, Philops. 25 sobre um mensageiro celestial: <span class=\"greek\">νεανίας</span> <span class=\"greek\">πάγκαλος</span> <span class=\"greek\">λευκὸν</span> <span class=\"greek\">ἱμάτιον</span> <span class=\"greek\">περιβεβλημένος</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:5</a>, 18; 4:4; 6:11; 7:9, 13. Uma veste é <span class=\"greek\">λ</span>. <span class=\"greek\">ὡς</span> <span class=\"greek\">χιών</span> (Da 7:9 Theod.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:3</a> (em oposição a vestes próprias para o luto: Aeschines, Against Ctesiphon 77); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:3</a> variante textual; Hs 8, 2, 3f. <span class=\"greek\">ἐν</span> <span class=\"greek\">λευκοῖς</span> (subentenda-se <span class=\"greek\">ἱματίοις</span>) vestidos de branco (Artem. 2, 3 p. 86, 17; 4, 2 p. 205, 9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:4</a>; Hv 4, 2, 1; Hs 8, 2, 4; <span class=\"greek\">βύσσινον</span> <span class=\"greek\">λ</span>. uma veste de linho branco <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:14b</a> (variante textual <span class=\"greek\">λευκοβύσσινον</span>). Quanto à roupa sacerdotal feita de linho branco (veja Schürer II 293) Ox 840, 27. Quanto aos calçados Hv 4, 2, 1.—GRadke, D. Bedeutg. d. weissen u. schwarzen Farbe in Kult u. Brauch d. Griech. u. Römer, diss. Berlin ’36; RGradwohl, D. Farben im AT, ’63, 34–50.—Sobre vestimentas especiais em algumas celebrações mistéricas, veja SCole, Theoi Megaloi ’84, 114 n. 125.—B. 1052; 1054. DELG. EDNT. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0218-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λέων, οντος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λέων</span>, <span class=\"greek\">οντος</span>, <span class=\"greek\">ὁ</span> (Hom.+; também BGU 957, 4 [10 a.C.]; PGrenf II, 84, 7) leão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.33\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:33</a>; MPol 12:2; Philo; AcPl Ha 2, 7; 4, 19; 34; 38; 5, 2; 4f; 9; 13; 18. Símbolo de voracidade 1 Cl 35:11 (Ps 49:22 variante textual [ARahlfs, Psalmi cum Odis ’31]). <span class=\"greek\">λάκκος</span> <span class=\"greek\">λεόντων</span> (veja <span class=\"greek\">λάκκος</span>) 45:6. Quanto ao diabo <span class=\"greek\">ὡς</span> <span class=\"greek\">λ</span>. <span class=\"greek\">ὠρυόμενος</span> <span class=\"greek\">περιπατεῖ</span> anda em derredor como leão que ruge <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:8</a> (Ps 21:14; TestSol 11:1 <span class=\"greek\">βρυχώμενος</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">λεών</span>; cf. JosAs 12:9 <span class=\"greek\">ὁ</span> <span class=\"greek\">λέων</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄγριος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">παλαιὸς</span> <span class=\"greek\">καταδιώκει</span> <span class=\"greek\">με</span>). O uso apocalíptico também apresenta comparações com o leão, com partes de seu corpo ou com suas ações (Il. 6, 181; Strabo 16, 4, 16 seres fabulosos: <span class=\"greek\">σφίγγες</span> <span class=\"greek\">κ</span>. <span class=\"greek\">κυνοκέφαλοι</span> <span class=\"greek\">κ</span>. <span class=\"greek\">κῆβοι</span> [macacos] <span class=\"greek\">λέοντος</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">ἔχοντες</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">λοιπὸν</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">πάνθηρος</span> <span class=\"greek\">κτλ</span>.; de modo muito semelhante Diod S 3, 35, 6; TestAbr A 17 p. 99, 21 [Stone p. 46]; Ath. 18, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:7</a>; 9:8 (cf. Jo 1:6), 17; 10:3; 13:2. Metaforicamente (cf. Il. 21, 483, a respeito de Ártemis) de um herói de coração leonino (cf. Lycophron 33 [Heracles]; Ael. Aristid. 46 p. 191f D. [Pericles]; Esth 4:17s; Jos., Ant. 18, 228), o Messias <span class=\"greek\">ὁ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">φυλῆς</span> <span class=\"greek\">Ἰούδα</span> o leão da tribo de Judá <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:5</a> (cf. Gen 49:9).—<span class=\"greek\">ῥυσθῆναι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">στόματος</span> <span class=\"greek\">λ</span>. ser livrado das fauces do leão, isto é, de grande perigo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:17</a> (cf. Ps 21:22). O leão voraz figura como motivo funerário, e tanto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:8</a> (acima) como <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:17</a> podem referir-se à morte (o primeiro à morte física, o segundo à morte espiritual ou à apostasia: New Docs 3, 50f).—OKeller, Die Antike Tierwelt, 2 volumes 1909–13: II 24–61. EGoodenough, Jewish Symbols VII, ’58, 29–86. Pauly-W. XIII/1 968–90.—B. 185. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0218-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λήθη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λήθη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (veja <span class=\"greek\">λανθάνω</span>, de que <span class=\"greek\">λήθω</span> é uma forma colateral; Homero e outros; Vett. Val. 242, 4; PCairMasp 4, 4; LXX; En 5:8 [Rademacher em lugar de <span class=\"greek\">ἀλήθειαν</span>]; TestJob 47:8; Philo; Jos., Ant. 15, 376; Just., D. 46, 5; Ath. 12:2) esquecimento <span class=\"greek\">λήθην</span> <span class=\"greek\">λαμβάνειν</span> <span class=\"greek\">τινός</span> esquecer algo (veja <span class=\"greek\">λαμβάνω</span> 10c) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:9</a>.—DELG s.v. <span class=\"greek\">λανθάνω</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0218-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῆμμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λῆμμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (veja <span class=\"greek\">λαμβάνω</span> e o verbete seguinte; Sófocles, Platão e outros; pap, LXX, Philo; Jos., Bell. 1, 289, Ant. 14, 393) algo recebido; ganho <span class=\"greek\">διὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐπιθυμίαν</span> <span class=\"greek\">ποῦ</span> <span class=\"greek\">λ</span>. por causa do desejo de lucro Hs 9, 19, 3.—DELG s.v. <span class=\"greek\">λαμβάνω</span> B.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0218-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῆμψις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λῆμψις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (as edições também apresentam <span class=\"greek\">λῆψις</span>; Sófocles, Tucídides e outros; PTebt 238 [século II a.C.]; POxy 71 I, 18. Quanto à grafia, veja a bibliografia apresentada no início do verbete <span class=\"greek\">λαμβάνω</span>, a propósito de <span class=\"greek\">λήμψομαι</span>) a condição de quem recebe algo, recebimento, como termo comercial <span class=\"greek\">ἐν</span> <span class=\"greek\">πικρίᾳ</span> <span class=\"greek\">γίνεσθαι</span> … <span class=\"greek\">περὶ</span> <span class=\"greek\">δόσεως</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λ</span>. tornar-se amargo … acerca de dar e receber, «débito e crédito» Hm 5, 2, 2. Em imagem comercial <span class=\"greek\">κοινωνεῖν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">δόσεως</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:15</a> (veja <span class=\"greek\">δόσις</span> 2; GPeterman, Paul’s Gift from Philippi ’97). Sobre o aspecto comercial, veja <span class=\"greek\">λόγος</span>.—DELG s.v. <span class=\"greek\">λαμβάνω</span> B. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0218-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ληνός, οῦ, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ληνός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ἡ</span> termo para algo côncavo, como uma cuba ou um cocho; daí também lagar (assim em Teócrito; Diod S 3, 63, 4; ins: Sb 7541, 11 [século II d.C.]; PAmh 48, 7 [106 a.C.]; POxy 729, 19; LXX; JosAs 2:20 «cocho»; Jos., Ant. 5, 213 al.; Just., D. 86, 2) <span class=\"greek\">γεννήματα</span> <span class=\"greek\">λ</span>. produto do lagar (cf. Num 18:30) D 13:3 (veja <span class=\"greek\">γέννημα</span>). Escavado na rocha (cf. POxy 502, 36 [164 d.C.] <span class=\"greek\">τὰς</span> <span class=\"greek\">ληνοὺς</span> <span class=\"greek\">λιθίνας</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:33</a>.—Em Apocalipse, figuradamente <span class=\"greek\">πατεῖν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">λ</span>. pisar o lagar (isto é, as uvas que nele estão; Diod S 4, 5, 1 <span class=\"greek\">πατῆσαι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">σταφυλὰς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ληνῷ</span>; veja também 2 Esdr 23:15; La 1:15; cf. Jer 31:33) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:15</a>; na voz passiva 14:20a. <span class=\"greek\">βάλλειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ληνόν</span> lançar no lagar (cf. Anacreontea 59, 4 Pr. <span class=\"greek\">κατὰ</span> <span class=\"greek\">ληνὸν</span> <span class=\"greek\">βάλλειν</span> … <span class=\"greek\">πατεῖν</span>) 14:19. Sangue (cf. o «sangue da uva») corre do lagar v. 20b.—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0218-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῆρος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λῆρος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Aristófanes e outros; X., An. 7, 7, 41; PSI 534, 16; 4 Macc 5:11; TestSol 26:6; Philo, Post. Cai. 165; Jos., Bell. 3, 405; Just., A I, 68, 1; Tat., Ath.) aquilo que é inteiramente desprovido de valor, conversa fiada, disparate, tolice, embuste <span class=\"greek\">ἐφάνησαν</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ὡσεὶ</span> <span class=\"greek\">λῆρος</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ῥήματα</span> <span class=\"greek\">ταῦτα</span> essas palavras lhes pareceram um disparate <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:11</a>. Veja <span class=\"greek\">ληρώδης</span>.—DELG 1. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0218-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ληρώδης, ες</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ληρώδης</span>, <span class=\"greek\">ες</span> (veja <span class=\"greek\">λῆρος</span> e o sufixo -<span class=\"greek\">ώδης</span>; Platão e outros; BGU 1011 II, 15 [século II a.C.]; 2 Macc 12:44; Philo, Leg. ad Gai. 168; Just., A I, 68, 1) insensato, tolo, frívolo <span class=\"greek\">οἱ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">λόγοι</span> as declarações insensatas Dg 8:2.—DELG s.v. 1 <span class=\"greek\">λῆρος</span>. M-M. s.v. <span class=\"greek\">λῆρος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0218-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῃστής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λῃστής</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">ληϊς</span>, forma épica de <span class=\"greek\">λεία</span>, «saque, despojos»; Soph., Hdt.+; ins, pap, LXX; ApcSed 15:3; Joseph.; empréstimo na literatura rabínica; Ar. 3, 2; Just., Tat., Ath., R. 19 p. 72, 25; Theoph. Ant. 3, 14 [p. 232, 13]).</p><p class=\"entry-text\">① ladrão, salteador de estrada, bandido (na Palestina: Jos., Bell. 2, 125; 228 al.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:30</a>, 36; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:26</a> (Chariton 6, 4, 6 <span class=\"greek\">λῃσταῖς</span> <span class=\"greek\">θαλάττῃ</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:55</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:52</a>; assim também MPol 7:1. Crucificados com Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:38</a>, 44; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:27</a>. Com <span class=\"greek\">κλέπτης</span> (Pla., Rep. 351c; Ep. 63 de Apolônio de Tiana [Philostrat. I 363, 21]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:1</a>, 8. <span class=\"greek\">σπήλαιον</span> <span class=\"greek\">λῃστῶν</span> uma caverna ou esconderijo de bandidos (Jer 7:11) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:46</a>; 2 Cl 14:1 (GBuchanan, HUCA 30, ’59, 169–77: «caverna de salteadores»; veja <span class=\"greek\">ἱερόν</span> b, ao final; Schürer II 600).—Esta acepção ampliou-se para designar</p><p class=\"entry-text\">② revolucionário, insurgente, guerrilheiro (Jos., Bell. 2, 254=<span class=\"greek\">σικάριος</span>; 253; 4, 504, Ant. 14, 159f; 20, 160f; 167) quanto a Barrabás (cf. <span class=\"greek\">μετὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">στασιαστῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:7</a>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:40</a> (HRigg, Jr., JBL 64, ’45, 444 n. 95; HWood, NTS 2, ’55/56, 262–66 e JTwomey, Scripture (Edinburgh) 8, ’56, 115–19 sustentam essa interpretação, mas veja MHengel, Die Zeloten, ’61, 25–47; 344–48); provavelmente também nas palavras de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:55</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:52</a>; MPol 7:1 (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:55</a>).—Uma definição mais precisa depende da avaliação do fenômeno do «banditismo social», veja RHorsley, Josephus and the Bandits: Journal for the Study of Judaism 10, ’79, 37–63; RHorsley/JHanson, Bandits, Prophets, and Messiahs ’85.—B. 791. DELG s.v. <span class=\"greek\">λεία</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0218-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῆψις</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λῆψις</span> veja <span class=\"greek\">λῆμψις</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0218-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίαν</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λίαν</span> advérbio (em Homero e outros como <span class=\"greek\">λίην</span>; como <span class=\"greek\">λίαν</span>, desde Píndaro) em alto grau, muito, extremamente, sobremaneira.</p><p class=\"entry-text\">ⓐ usado com verbos, precedendo-os (EpArist 312; Jos., Vi. 404) <span class=\"greek\">λ</span>. <span class=\"greek\">ἀντέστη</span> ele se opôs veementemente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:15</a>. <span class=\"greek\">λ</span>. <span class=\"greek\">πρόσεχε</span> guarda-te com extremo cuidado D 6:3. <span class=\"greek\">λ</span>. <span class=\"greek\">ἐκκέχυμαι</span> <span class=\"greek\">ἀγαπῶν</span> <span class=\"greek\">ὑμᾶς</span> derramo sobre vós o meu amor IPhld 5:1. <span class=\"greek\">ὅταν</span> … <span class=\"greek\">λ</span>. <span class=\"greek\">πικρανθῇ</span> quando a pessoa se torna extremamente amargurada Hm 10, 2, 3; cf. 9:9b; 12, 1, 2; 12, 4, 1; Hs 5, 2, 7; 6, 2, 7; 7:1; 8, 3, 8; 9, 11, 3. Depois do verbo (Gen 4:5) <span class=\"greek\">ἐθυμώθη</span> <span class=\"greek\">λ</span>. ele ficou muito irado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:16</a>. <span class=\"greek\">θαυμάζειν</span> … <span class=\"greek\">λ</span>. 27:14; <span class=\"greek\">ἔκλαυσα</span> <span class=\"greek\">λ</span>. chorei amargamente Hm 3:3; <span class=\"greek\">ἐχάρη</span> <span class=\"greek\">λ</span>. ele ficou muito alegre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:8</a>; Hs 5, 2, 5; 8, 1, 16; também <span class=\"greek\">λ</span>. <span class=\"greek\">ἐχάρη</span> 5, 2, 11. Numa carta <span class=\"greek\">ἐχάρην</span> <span class=\"greek\">λ</span>. fiquei muito alegre (BGU 632, 10; PGiss 21, 3) 2J 4; 3J 3. <span class=\"greek\">ἐλυπήθη</span> <span class=\"greek\">λ</span>. (Caim) ficou profundamente entristecido 1 Cl 4:3 (cf. Gen. 4:5). Intensificado, <span class=\"greek\">λίαν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">περισσοῦ</span>: inteiramente, sobremaneira <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.51\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:51</a>.</p><p class=\"entry-text\">ⓑ usado com adjetivos, que</p><p class=\"entry-text\"><span class=\"greek\">α</span>. funcionam como adjuntos atributivos (SIG 1102, 12 <span class=\"greek\">αἱ</span> <span class=\"greek\">λίαν</span> <span class=\"greek\">ἄκαιροι</span> <span class=\"greek\">δαπάναι</span>): precedendo o(s) adjetivo(s): <span class=\"greek\">καὶ</span> <span class=\"greek\">γε</span> <span class=\"greek\">λ</span>. <span class=\"greek\">πιστοὺς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἱσχυρούς</span> também muito dedicados e firmes Hs 9, 9, 9a; <span class=\"greek\">λ</span>. <span class=\"greek\">ὑψηλός</span> que cresceu muito alto Hs 8, 1, 2; <span class=\"greek\">λ</span>. <span class=\"greek\">εὐειδής</span> muito encantadora AcPl Ha 3, 13. Depois do adjetivo: <span class=\"greek\">ὄρος</span> <span class=\"greek\">ὑψηλὸν</span> <span class=\"greek\">λ</span>. muito alto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:8</a>; <span class=\"greek\">χαλεποὶ</span> <span class=\"greek\">λ</span>. muito perigosos 8:28. <span class=\"greek\">ἀψινθίου</span> <span class=\"greek\">μικρὸν</span> <span class=\"greek\">λ</span>. somente um pouquinho Hm 5, 1, 5. <span class=\"greek\">πρόβατα</span> <span class=\"greek\">πολλὰ</span> <span class=\"greek\">λ</span>. muitíssimas ovelhas Hs 6, 1, 6a. <span class=\"greek\">ῥάβδον</span> <span class=\"greek\">σκληρὰν</span> <span class=\"greek\">λ</span>. uma vara muito resistente 6, 2, 5. <span class=\"greek\">πικρὸν</span> <span class=\"greek\">λ</span>., muito feroz, AcPl Ha 4, 20.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. funcionam como predicativos, precedendo (Diod S 14, 58, 2 <span class=\"greek\">λίαν</span> <span class=\"greek\">ὀχυρός</span>; PTebt 315, 18 <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">λείαν</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">αὐστηρός</span>; TestJob 13:6 <span class=\"greek\">λ</span>. <span class=\"greek\">μου</span> <span class=\"greek\">χρηστοῦ</span> <span class=\"greek\">ὄντος</span>) <span class=\"greek\">αἰσχρὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">αἰσχρά</span> vergonhosas, muito vergonhosas 1 Cl 47:6. <span class=\"greek\">λ</span>. <span class=\"greek\">ἄφρων</span> <span class=\"greek\">εἰμί</span> Hm 4, 2, 1; cf. <span class=\"greek\">κἂν</span> <span class=\"greek\">λ</span>. <span class=\"greek\">σύνετος</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">τις</span> Hs 5, 5, 4. <span class=\"greek\">ὤφθη</span> … <span class=\"greek\">μοι</span> … <span class=\"greek\">λ</span>. <span class=\"greek\">πρεσβυτέρα</span> uma mulher muito idosa v 3, 10, 3; cf. m 8, 6; Hs 2:5; 5, 3, 5; 6, 1, 6bc; 6, 2, 3; 8, 1, 17f; 9, 1, 7b; 10a; 9, 2, 4; 9, 3, 1; 9, 6, 8; 9, 9, 2; 7. Depois (Gen 1:31; Tob 6:12 S) <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">λευκὰ</span> <span class=\"greek\">λ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:3</a>. <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">ἀγαπητὸν</span> <span class=\"greek\">λ</span>. <span class=\"greek\">ἔχετε</span> por quem tendes especial afeição 1 Pol 7:2. <span class=\"greek\">περίλυπος</span> <span class=\"greek\">ἤμην</span> <span class=\"greek\">λ</span>. eu estava extremamente triste Hv 3, 10, 6. <span class=\"greek\">ἐντολαὶ</span> … <span class=\"greek\">σκληραὶ</span> … <span class=\"greek\">σκληραί</span> <span class=\"greek\">εἰσι</span> muito exigentes ou severas m 12, 3, 4; (<span class=\"greek\">λίθοι</span>) <span class=\"greek\">σκληροὶ</span> … <span class=\"greek\">λ</span>. <span class=\"greek\">εὑρέθησαν</span> revelaram-se duros demais para lavrar ou moldar Hs 9, 8, 6. <span class=\"greek\">αὐθάδης</span> <span class=\"greek\">εἶ</span> <span class=\"greek\">λ</span>. és muito obstinado 5, 4, 2. Cf. 9, 1, 7a; 10b; 9, 9, 4.</p><p class=\"entry-text\">ⓒ usado com advérbio, vindo depois dele (Da 11:25) <span class=\"greek\">πρωὶ̈</span> <span class=\"greek\">ἔννυχα</span> <span class=\"greek\">λ</span>. bem cedo de manhã, quando ainda estava bastante escuro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:35</a>. Vindo antes dele (2 Macc 11:1; EpArist 230; Jos., C. Ap. 1, 286; 2, 3; Tat. 2, 1; 21, 3; PMich 154, 17 <span class=\"greek\">λ</span>. <span class=\"greek\">νυκτός</span>) <span class=\"greek\">λ</span>. <span class=\"greek\">πρωί̈</span> muito cedo de manhã 16:2. <span class=\"greek\">λ</span>. <span class=\"greek\">ὀργίλως</span> <span class=\"greek\">ἐλάλησεν</span> com intensa ira Hm 12, 4, 1. Veja <span class=\"greek\">ὑπερλίαν</span>.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0218-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίβα</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λίβα</span> veja <span class=\"greek\">λίψ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0218-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λίβανος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Λίβανος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Theophr., On Plants 9, 7, 1; Diod S 19, 58, 2f) (o) Líbano, cadeia montanhosa na Síria que acompanha a costa mediterrânea, famosa por seus cedros 1 Cl 14:5 (Ps 36:35).—Pauly-W. XIII, 1, 1–11. ABD IV 269f.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0218-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίβανος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λίβανος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (=a árvore do incenso, segundo Heródoto e outros; =a resina aromática, desde Píndaro; cf. Phryn. 187 Lob.) olíbano, resina gomosa branca obtida de diferentes espécies de determinada árvore da Arábia, usada medicinalmente e em ritos religiosos (EMaehler, ZPE 4, ’69, 99; Zohary, Plants 197). 1 Cl 25:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:13</a>. Com ouro e mirra, como presente valioso (o olíbano da melhor qualidade custava seis denários por aproximadamente .4 kg; Plínio, HN 12, 65) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:11</a>; GJs 21:3 (cf. Diod S 19, 94, 5; Is 60:6; sobre olíbano e mirra juntos, veja Diod S 3, 46, 3; Strabo 16, 4, 14 p. 774; Polyaenus 8, 26; En 29:2; PGM 13, 354.—Já em Empédocles 128, 6 [Vorsokr. 31] <span class=\"greek\">σμύρνη</span> e <span class=\"greek\">λίβανος</span> são oferendas sacrificiais apropriadas aos deuses. SibOr 3, 772: presente messiânico).—ILöw, D. Flora d. Juden I 1928, 312–14; GvanBeek, BA 23, ’60, 70–95; WMüller, Glotta 52, ’74, 53–59; JBrown, JSS 25, ’80, 16–21; New Docs 4, 129–31 (Connolly).—DELG. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0218-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιβανωτός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λιβανωτός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span></p><p class=\"entry-text\">① incenso, olíbano (assim em Heródoto e outros; Diod S 2, 49, 2 [oferecido aos deuses em todo o mundo]; OGI 383, 142 [século I a.C.] <span class=\"greek\">λιβανωτοῦ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἀρωμάτων</span>; e outros, em inscrições; PHib 121, 54 [século III a.C.]; POxy 118, 20; 234 II, 38; Mayser 40; 1 Ch 9:29 <span class=\"greek\">λ</span>. <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀρωμάτων</span>; 3 Macc 5:2; Philo, Spec. Leg. 1, 275; Jos., Ant. 3, 256) <span class=\"greek\">ὡς</span> <span class=\"greek\">λιβανωτοῦ</span> <span class=\"greek\">πνέοντος</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἄλλου</span> <span class=\"greek\">τινὸς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀρωμάτων</span> MPol 15:2.</p><p class=\"entry-text\">② incensário, recipiente no qual se queima o incenso <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:3</a>, 5.—New Docs 4, 129–31 (Connolly). DELG s.v. <span class=\"greek\">λίβανος</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0218-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λιβερτῖνος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Λιβερτῖνος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (empréstimo do latim libertinus, que designa uma pessoa alforriada; IG XIV, 1781) liberto, pessoa alforriada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:9</a>, designação de certos israelitas em Jerusalém que possuíam sua própria sinagoga (Schürer II 76; 428, 8; III 133, 26; Ltzm., ZNW 20, 1921, 172; a tentativa de GdeRossi, Bull. di arch. christ. 1864, 70; 92f, de interpretar CIL, IV 117 como referência a uma suposta sinagoga de libertos em Pompeia é rejeitada em Beginn. IV 67). A designação descreve essas pessoas como antigos escravos ou seus descendentes. A alteração para <span class=\"greek\">Λιβυστίνων</span>, conjecturada por Beza no século 16 (RHarris, ET 6, 1895, 378–90) e registrada em Estêvão de Bizâncio (s.v. <span class=\"greek\">Λίβυς</span>)=«líbios» (assim na versão armênia) é favorecida por FBlass, Philol. of the Gospels 1898, 69f; Moffatt; Goodsp., Probs. 127–30, mas é considerada «atraente, porém desnecessária» por Jackson e Lake, Beginn. III 58; sobre a relação entre a dicção e a sintaxe de Lucas e a interpretação do termo, veja ISBE II, ’82, 360.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0218-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λιβύη, ης, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Λιβύη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (Homero e outros; OGI 54, 5 [século III a.C.]; Sb 4456 lápide funerária [século II a.C.] e outros, em inscrições e papiros [Mayser 101]; Philo, Joseph., SibOr) Líbia, região da África setentrional entre o Egito e Cirene; a parte ocidental, a Líbia Cirenaica, é designada por <span class=\"greek\">τὰ</span> <span class=\"greek\">μέρη</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Λ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">Κυρήνην</span> as regiões da Líbia próximas a Cirene <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:10</a> (Jos., Ant. 16, 160 <span class=\"greek\">ἡ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">Κυρήνῃ</span> <span class=\"greek\">Λιβύη</span>).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0218-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λιβυστῖνος</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Λιβυστῖνος</span> veja <span class=\"greek\">Λιβερτῖνος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0218-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λιθάζω</span> 1º aoristo <span class=\"greek\">ἐλίθασα</span>; na voz passiva, <span class=\"greek\">ἐλιθάσθην</span> (<span class=\"greek\">λιθάς</span> [=<span class=\"greek\">λίθος</span>] Mlt-H. 404; desde o comediógrafo Anaxândrides [século IV a.C.], Fgm. 16; Aristot., geralmente em uso absoluto, «atirar pedras»; 2 Km 16:6, 13; Jos., C. Ap. 2, 206 cod.) apedrejar <span class=\"greek\">τινά</span>, alguém. No Antigo Testamento e na Mishná (Sanhedrin 6; 7, 4–8, 5), o apedrejamento era uma forma de pena capital por determinados crimes: adultério <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:5</a> (variante textual <span class=\"greek\">λιθοβολεῖσθαι</span>; veja esse verbete); especialmente a blasfêmia contra Deus; por vezes, a população se exaltava e assumia a tarefa de pronunciar e executar tal sentença: 10:31ff (sobre <span class=\"greek\">λιθάζετε</span> no v. 32, «estais tentando apedrejar», cf. Rob. 880); 11:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:26</a>; 14:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:25</a>; 1 Cl 5:6; GPt 11:48. Juntamente com outras formas de morte <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.37\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:37</a>; cf. 1 Cl 45:4.—RHirzel, Die Strafe der Steinigung: Abh. d. Sächs. Ges. d. Wiss. 27, 1909, 223–66; JBlinzler, Moule Festschr. ’70, 147–61.—DELG s.v. <span class=\"greek\">λίθος</span>. M-M. TW.</p></section></article>"};
